"""Preserve seven fifth-rank Illusion sources and their concrete open questions."""
import json
from prepare_spell_source_cohort import prepare, AUDIT

QUESTIONS = {
    'mass-mirage': 'Preserve UP TO6 targets appearing as others, expressly including VOICE and SILHOUETTE, Core Action/60ft/Instantaneous. Define valid creature targets, willingness/save, sight/line, independent disguise choices and finite duration/concentration. Establish dimensions and apparent equipment limits, moving-image behavior, sound production versus knowledge of a voice/language, inspection/touch/disbelief, and interaction with true sight and the reviewed Disguise Self/Distort Voice. Do not reduce the six-target/voice clauses to a generic visual disguise. It grants no actual form, hitbox, size, fit, carrying, anatomy, class ability, credentials or successful deception. Resolve one recipient losing the disguise, suppression, death, subsequent shapechange and recasts without refreshing unrelated resources or exposing all other targets.',
    'veil-of-terror': 'Preserve one enemy perceiving its worst fear, WIS save or Frightened PLUS4d6 psychic, Core Action/60ft/concentration up to one minute. Define initial and repeat save timing, one-time versus expressly NEW recurring damage, damage/control success outcomes and an actual fear-source anchor for the existing Frightened condition. Decide whose senses perceive the image, required sight/mental perception, initial eligibility and whether immunity to fear removes only fear or also damage. The image must not automatically reveal the target\'s private memories or true fear to the caster. Compare reviewed Fear/Hypnotic Pattern and the pending Phantasmal Killer variants without importing their damage cadence. No action denial, flight command, real creature or damage merely because the illusion persists; suppression and recasting preserve actual clocks and control history.',
    'echofield': 'Preserve an area repeating sounds RANDOMLY, STEALTH IMPOSSIBLE and confusion of enemies, Core Action/60ft/Instantaneous. Define finite geometry, lifetime, which real sounds can be recorded/replayed, retention window, random timing/selection and volume; no invented distant secret audio or semantic surveillance. Resolve the exact scope of stealth impossible, including visual hiding,silent motion,Deafened recipients, Silence and invisibility, without quietly dropping that printed clause or granting omniscient location knowledge. Define confuses as a finite mechanical component with save,cadence and endpoint, or an explicit information consequence; do not silently import the separate Confusion spell. Identify enemy eligibility from actual information, record overlap/entry/exit/suppression, and keep copies from becoming infinite sound sources or new casting components.',
    'phantom-swarm': 'Preserve illusory insects dealing5d6 psychic and requiring TARGETS to move away, Core Action/60ft/Instantaneous. Define number/area, origin, finite geometry, actual target and sensory eligibility, save outcomes for damage and compelled movement separately. State away from which fixed source, distance or ordinary movement budget, legal routes, timing, opportunity attacks and blocked/no-safe-route behavior. Reconcile existing compelled-budget priority and hard-control admission where actually applicable, without silently adding fear, extra turns, Dash or unlimited movement. No physical insects, occupied spaces, swarms with statblocks, poison, terrain, food, harvestable bodies or concentration rider arise from flavor. Clarify whether immunity to illusions, psychic damage or fear affects either component only within its real scope; no repeated damage from extra turns or reentry.',
    'seeming': 'Preserve changing the appearance of ANY NUMBER of creatures, Core Action/60ft/Instantaneous. Define a finite actual target snapshot within range and line of effect; any number is not an invented six-creature cap or future blanket enrollment. Supply willingness/save, lifetime/concentration and exact permitted visual changes, including silhouette,size envelope and apparent possessions, without importing Mass Mirage\'s express voice benefit. Compare Disguise Self, Mass Mirage and actual shapechange/gear rules. Define inspection,touch,disbelief,true sight,independent endings,suppression and recasts while preserving each real body. Appearance grants no extra limbs, equipment, AC, ability scores, ancestry traits, legal identity, knowledge or automatic acceptance by observers. Instantaneous cannot leave an undefined permanent effect.',
    'creation': 'Preserve creating ONE NONLIVING OBJECT of VEGETABLE MATTER, Core Action/60ft/Instantaneous. Do not reduce creation to a harmless illusion or silently import another game\'s mineral ladder and durations. Define finite mass/volume/dimensions, actual material classes, complexity and required pattern/knowledge, legal empty placement, lifetime versus permanent matter and any concentration. Decide structural HP/AC,functionality,quality,ownership,split/consumed/processed states and suppression/dispel treatment explicitly. Resolve food,potable supplies,fuel,reagents,substrates,complete tool bodies,crafting value and sale against the reviewed crafting/Cooking/Fishing physical-identity ledgers. If useful permanent stock is authorized, state its bounded source identity and real economic consequences instead of claiming the existing conservation rules prohibit the printed creation effect. No monster donor traits,magic formula,unique material,live organism or cosmological origin is established by vegetable matter. Identify exact work/tool qualifications and prevent copies from also claiming an absent original material lot.',
    'dream': 'Preserve sending a MESSAGE to a SLEEPING TARGET OR creating a NIGHTMARE, Core Action/60ft/Instantaneous. Resolve both modes separately with actual target identity, current sleep eligibility, perception/line of effect or an explicit source-bound exception, message length/comprehension and lifetime; do not silently grant world-spanning range. Define whether waking interrupts, whether the recipient can answer, and what the caster knows about success without exposing protected sleep/location information. Nightmare needs a finite mechanical consequence,save,timing and recovery rule if NEW; no unprinted HP damage, exhaustion, lost rest or compulsive command is assumed. Compare reviewed Sleep and information/privacy boundaries. Treat dreams as the target\'s experience for this mechanical question; no dream plane,soul travel,theology or cosmology review occurs before the verified push. Recasts, suppression and successive rests cannot create unbounded queued messages or penalties.'
}


def main():
    coverage = json.loads((AUDIT / 'FOCUSED_SPELL_SOURCE_PREPARATION_COVERAGE.json').read_text(encoding='utf-8'))
    assert len(coverage['cohortFiles']) == 13 and coverage['distinctPreparedPendingSpellIds'] == 217
    prepare(
        prefix='ILLUSION_RANK5', title='Rank-five Illusion source audit', questions=QUESTIONS,
        selector=lambda r: r['operational'] is None and 'Illusion' in r['schools'] and min(v['rank'] for v in r['classAccess'].values()) == 5,
        expected_count=7, question_prefix='IL5', prior_files=coverage['cohortFiles'], expected_prior_count=217,
        counterpart_ids=['disguise-self', 'distort-voice', 'ghost-sound', 'minor-image', 'minor-illusion',
                         'mirror-image', 'silent-image', 'fear', 'hypnotic-pattern', 'sleep'],
        pending_ids=['phantasmal-killer', 'confusion', 'compulsion', 'group-illusion', 'fabricate'],
        extra_excerpts={
            'CONDITIONS_PLAYTEST.md': ['Unconscious'],
            'CRAFTING_HARVEST_PLAYTEST.md': None,
            'COOKING_RECIPE_PLAYTEST.md': ['Food mass and the food ledger', 'Containers and capacity', 'Cooking, stabilization and storage'],
            'FISHING_RECIPE_PLAYTEST.md': ['Real material recovery', 'Value, food and the Supply boundary'],
        },
        introduction='Seven pending identities preserve their complete source and current-book records. Mass Mirage explicitly includes six targets,voice and silhouette; Seeming has any-number appearance wording. Creation really promises an object and therefore needs material/economy decisions, not deletion of its effect. Dream is framed only as mechanical messaging/nightmare questions; no cosmological interpretation is adopted. Earlier source packets and operational records remain unchanged.',
        future_dispatch='Prepared only; the live notebook is reviewing Mining/shared gathering sources. Rebase exact dependencies before this future spell conference and preserve the current revision. Source decisions precede authored cards and exact review. All cosmology questions remain after the authorized push and verified remote commit.')


if __name__ == '__main__':
    main()
